const config = {
    baseTopic: "domoticsai/v1",
    version: "0.1.0",
    mode: "LIVE_READ_ONLY",
    allowLegacyCommands: false,
    startedAt: new Date().toISOString()
};
global.set("domoticsai_config", config);
msg.topic = `${config.baseTopic}/log/gateway`;
msg.payload = {
    ts: new Date().toISOString(),
    level: "INFO",
    component: "core",
    event: "GATEWAY_INITIALIZED",
    details: config
};
return msg;

const config = global.get("domoticsai_config") || {baseTopic:"domoticsai/v1"};
msg.topic = `${config.baseTopic}/log/gateway`;
msg.payload = {
    ts: new Date().toISOString(),
    level: "ERROR",
    component: msg.error?.source?.name || "unknown",
    event: "NODE_RED_ERROR",
    message: msg.error?.message || "Unknown error"
};
return msg;

const config = global.get("domoticsai_config") || {baseTopic:"domoticsai/v1"};
msg.topic = `${config.baseTopic}/log/gateway`;
msg.payload = {
    ts: new Date().toISOString(),
    level: "INFO",
    component: msg.status?.source?.name || "node-red",
    event: "NODE_STATUS",
    status: msg.status?.text || "",
    fill: msg.status?.fill || "",
    shape: msg.status?.shape || ""
};
return msg;

const config = global.get("domoticsai_config") || {
    baseTopic:"domoticsai/v1",
    version:"0.1.0",
    mode:"SIMULATION"
};
msg.topic = `${config.baseTopic}/availability/gateway`;
msg.payload = JSON.stringify({
    status:"online",
    ts:new Date().toISOString(),
    version:config.version,
    mode:config.mode
});
msg.qos = 1;
msg.retain = true;
return msg;

const base = (global.get("domoticsai_config") || {baseTopic:"domoticsai/v1"}).baseTopic;
const text = msg.status?.text || "";
const online = /connected/i.test(text) && !/disconnected/i.test(text);
msg.topic = `${base}/availability/production_mqtt_20`;
msg.payload = JSON.stringify({
    status: online ? "online" : "offline",
    detail: text,
    ts: new Date().toISOString(),
    readOnly: true
});
msg.qos = 1;
msg.retain = true;
return msg;

