const config = global.get("domoticsai_config") || {
    baseTopic:"domoticsai/v1",
    mode:"SIMULATION",
    allowLegacyCommands:false
};
const p = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
if (!p || typeof p.commandId !== "string" || typeof p.value !== "boolean") {
    msg.topic = `${config.baseTopic}/ack/${p?.commandId || "unknown"}`;
    msg.payload = JSON.stringify({
        commandId:p?.commandId || null,
        status:"rejected",
        error:"INVALID_PAYLOAD",
        ts:new Date().toISOString()
    });
    return [msg, null];
}
if (config.mode !== "SIMULATION" || config.allowLegacyCommands !== false) {
    msg.topic = `${config.baseTopic}/ack/${p.commandId}`;
    msg.payload = JSON.stringify({
        commandId:p.commandId,
        status:"rejected",
        error:"SAFETY_GUARD",
        ts:new Date().toISOString()
    });
    return [msg, null];
}
const ack = {
    topic:`${config.baseTopic}/ack/${p.commandId}`,
    payload:JSON.stringify({
        commandId:p.commandId,
        status:"confirmed",
        simulated:true,
        ts:new Date().toISOString()
    }),
    qos:1,
    retain:false
};
const log = {
    topic:`${config.baseTopic}/log/command`,
    payload:{
        ts:new Date().toISOString(),
        level:"INFO",
        component:"climate",
        event:"SIMULATED_COMMAND",
        commandId:p.commandId,
        requestedValue:p.value
    }
};
return [ack, log];

const config = global.get("domoticsai_config") || {baseTopic:"domoticsai/v1"};
const value = Number.parseInt(msg.payload); if (!Number.isInteger(value)) return null; const unit = "level";
msg.topic = `${config.baseTopic}/state/vmc/speed`;
msg.payload = JSON.stringify({
    value,
    unit,
    ts:new Date().toISOString(),
    quality:"good",
    source:"legacy"
});
msg.qos = 1;
msg.retain = true;
return msg;

const config = global.get("domoticsai_config") || {
    baseTopic:"domoticsai/v1",
    mode:"SIMULATION"
};
if (config.mode !== "SIMULATION") return null;

const now = Date.now();
const wave = Math.sin(now / 60000);
const ts = new Date().toISOString();

return [
    {
        topic:`${config.baseTopic}/state/energy/solar_power_w`,
        payload:JSON.stringify({value:Math.round(2600 + wave*600),unit:"W",ts,quality:"simulated"}),
        qos:1,retain:true
    },
    {
        topic:`${config.baseTopic}/state/energy/home_load_w`,
        payload:JSON.stringify({value:Math.round(1200 + wave*180),unit:"W",ts,quality:"simulated"}),
        qos:1,retain:true
    },
    {
        topic:`${config.baseTopic}/state/energy/powerwall_soc_pct`,
        payload:JSON.stringify({value:84.2,unit:"%",ts,quality:"simulated"}),
        qos:1,retain:true
    },
    {
        topic:`${config.baseTopic}/state/climate/living_temperature_c`,
        payload:JSON.stringify({value:Number((24.3 + wave*0.3).toFixed(1)),unit:"°C",ts,quality:"simulated"}),
        qos:1,retain:true
    },
    {
        topic:`${config.baseTopic}/state/climate/living_humidex`,
        payload:JSON.stringify({value:Number((29.8 + wave*0.4).toFixed(1)),unit:"",ts,quality:"simulated"}),
        qos:1,retain:true
    },
    {
        topic:`${config.baseTopic}/state/vmc/speed`,
        payload:JSON.stringify({value:2,unit:"level",ts,quality:"simulated"}),
        qos:1,retain:true
    }
];

const config = global.get("domoticsai_config") || {
    baseTopic: "domoticsai/v1"
};

const gridPowerW = Number(msg.payload);

if (!Number.isFinite(gridPowerW)) {
    return null;
}

const timestamp = new Date().toISOString();

const gridMessage = {
    topic: `${config.baseTopic}/state/energy/grid_power_w`,
    payload: JSON.stringify({
        value: Math.abs(gridPowerW) < 20 ? 0 : gridPowerW,
        unit: "W",
        ts: timestamp,
        quality: "good",
        source: "legacy",
        semantics: "positive_import_negative_export"
    }),
    qos: 1,
    retain: true
};

const solarPowerW = Number(
    flow.get("energy_solar_power_w")
);
const homeLoadW = Number(
    flow.get("energy_home_load_w")
);

let batteryMessage = null;

if (
    Number.isFinite(solarPowerW) &&
    Number.isFinite(homeLoadW)
) {
    const batteryPowerW =
        homeLoadW - solarPowerW - gridPowerW;

    batteryMessage = {
        topic: `${config.baseTopic}/state/energy/battery_power_w`,
        payload: JSON.stringify({
            value: Math.abs(batteryPowerW) < 20
                ? 0
                : batteryPowerW,
            unit: "W",
            ts: timestamp,
            quality: "calculated",
            source: "gateway",
            semantics: "positive_discharge_negative_charge"
        }),
        qos: 1,
        retain: true
    };
}

return [gridMessage, batteryMessage];
